  `news_date_created` bigint(20) unsigned NOT NULL,
  `news_date_modified` bigint(20) unsigned NOT NULL DEFAULT '0',
  `news_view` bigint(20) unsigned NOT NULL DEFAULT '0',
  `news_gallery` varchar(500) COLLATE utf8_bin NOT NULL,
