INSERT INTO `news` VALUES (34,'','',22,'DẠY PHA CHẾ TRÀ SỮA TRÂN CHÂU - TRÀ THÁI NGON','<div>\n<div class=&#34;wcustomhtml&#34; style=&#34;width:100%;&#34; align=&#34;left&#34;>\n<div style=&#34;background-color:#499413;padding:10px;&#34; align=&#34;center&#34;>\n<p style=&#34;color:#fcfcfc;font-size:23px;font-family:Arial;font-weight:bold;text-align:justify;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Khóa học dạy pha chế trà sữa - Trà Thái</span></p>\n</div>\n</div>\n</div>\n<div style=&#34;text-align:justify;&#34;>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff0000;background-color:#ffffff;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/catalogweb-copy.jpg&#34; alt=&#34;trung tam day tra sua ngon&#34; width=&#34;970&#34; /></span></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff0000;background-color:#ffffff;&#34;>1.Mục tiêu</span>: <span style=&#34;color:#000000;&#34;>Trang bị cho học viên các kiến thức sau:</span></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Khóa dạy học pha chế trà sữa ngon nhất cho chủ quán tự tin mở quán kinh doanh, trang bị đầy đủ kiến thức kinh nghiệm bước đầu xây dựng nên quán trà sữa.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Tìm hiểu<span style=&#34;background-color:#ffffff;&#34;> sự thành công của các quán trà</span> sữa thương hiệu nổi tiếng như: Phúc Long, Hot and Cold, - 18<sup>0</sup>C , Trà Tiên Hưởng, Gong Cha, Hoa Hướng Dương, Tea Cup....</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><iframe src=&#34;//www.youtube.com/embed/GeROQHr7Mxo&#34; width=&#34;600&#34; height=&#34;286&#34;></iframe></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><span style=&#34;font-size:10pt;&#34;><em>Video lớp học trà sữa</em> </span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- <span style=&#34;background-color:#ffffff;&#34;>Cách tạo nên thương hiệu </span>cho quán trà sữa mới hình thành.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;background-color:#ffffff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Phát triển ngay công thức mới cho quán để tạo sự cạnh tranh.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;background-color:#ffffff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Cập nhật liên tục các món mới của quán trà sữa.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Nguyên liệu pha chế trà sữa.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Dụng cụ pha chế kinh doanh trà sữa.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img src=&#34;http://phache.com.vn/upload/image/20160930_180406-web.jpg&#34; alt=&#34;lop hoc pha che tra sua&#34; width=&#34;600&#34; /></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><em><span style=&#34;font-size:10pt;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;>Thầy Lê Hữu Trí cùng các anh chị học viên lớp cao cấp ngày 28/09/2016</span></span></em></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Công thức pha chế các loại trà sữa đài loan, trà sữa thái lan, hồng trà, lục trà, lipton, yo shake, milk shake, cách chế biến FLAN, rau câu phomai, nấu trân châu ngon, được truyền ngay các bí quyết nấu thạch nhà làm ngon và chi phí thấp kinh doanh an toàn lợi nhuận cao.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> <img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/khoa-hoc-05-12-15.jpg&#34; alt=&#34;lop pha che tra sua ngon&#34; width=&#34;600&#34; height=&#34;338&#34; /></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><span style=&#34;color:#000000;font-size:10pt;font-family:&#39;times new roman&#39;, times;&#34;><em>Lớp nấu thạch phô mai chuyên nghiệp 05-12-2015</em></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Bí quyết pha trà sữa MILK FOAM và hồng trà MILK FOAM theo công nghệ nổi tiếng Đài Loan, váng sữa MACHIATO</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Hỗ trợ suốt đời nếu quên công thức.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Cách lên menu quán.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Tình hình kinh doanh trà sữa hiện tại.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Hướng dẫn kinh doanh như hoạch định chi phí, dự tính lãi lỗ.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Bí quyết tăng lượng khách cho quán.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0;margin-right:0;text-align:center;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img src=&#34;http://phache.com.vn/upload/image/hinh-anh-lop-hoc-pha-che-tra-sua-1.jpg&#34; alt=&#34;lop hoc tra sua ngon&#34; width=&#34;600&#34; height=&#34;338&#34; /></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0;margin-right:0;text-align:center;&#34;><span style=&#34;color:#000000;font-size:10pt;font-family:&#39;times new roman&#39;, times;&#34;><em>Hình ảnh khóa học ngày 11/12/2014</em></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;background-color:#ffffff;&#34;><strong><span style=&#34;color:#000000;font-size:14pt;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;>2. Nội dung khóa học:</span></span></strong></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff0000;&#34;>Phần 1</span>: <span style=&#34;color:#000000;&#34;>Tìm hiểu về dụng cụ và nguyên liệu dùng trong quán trà sữa để pha chế các loại thức uống.</span></span><br /><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Giới thiệu các dụng cụ cần thiết trong một quán trà sữa.</span><br /><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Giới thiệu về nguyên liệu dùng trong pha chế các loại đồ uống của quán trà sữa. Từ nguyên liệu cao cấp, chất lượng tốt, giá cả tốt dùng trong các quán trà sữa lớn và những loại nguyên liệu giá thấp bình dân phù hợp cho kinh doanh nhỏ giá thấp.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/hinh-anh-pha-che-dep.jpg&#34; alt=&#34;pha che dep thuc uong ngon&#34; width=&#34;600&#34; height=&#34;449&#34; /></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;><span style=&#34;font-size:12pt;&#34;><em>lớp học pha chế chuyên nghiệp ngày 25/03/2015 </em></span></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff0000;&#34;>Phần 2</span>: <span style=&#34;color:#000000;&#34;>Học pha chế các loại đồ uống.</span></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;>\n<p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Chương trình học khóa dạy học cách pha chế ngon làm chủ quán trà sữa - cafe - sinh tố - kem:</span></p>\n<p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;> 1) Dạy học cách pha chế ngon:</span></p>\n<p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;> - Tea (Trà):</span></p>\n<ul><li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Hot/cold tea ( trà nóng hoặc trà uống với đá): trà gừng, trà mơ, trà đào, trà tắc, trà chanh, trà thảo mộc.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>World tea ( trà thế giới): trà Thái, trà Ấn Độ, Trà Nhật, Trà Đạo....</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Milk foam tea: Trà màng sữa ngon các loại của đài loan.</span></li>\n</ul><p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>- Milk Tea (Trà sữa):</span></p>\n<ul><li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Taiwan Milk Tea ( trà sữa Đài Loan): đầy đủ từ cơ bản đến nâng cao các dòng trà sữa.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Các công thức sáng tạo trà sữa cho quán mới.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thailand Milk Tea ( trà sữa Thái Lan).</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Japan Tea ( Trà sữa Nhật Bản).</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Milk Tea Milk Foam: Các loại trà sữa màng sữa ngon Đài Loan.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Jelly and Flan ( thạch và bánh Flan trong trà sữa) Thạch nhà làm tự nhiên an toàn.</span></li>\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;> Jelly in Milk Tea: Các loại thạch trong trà sữa ngon như thạch trái cây các loại như: thạch dâu, thạch nha đam (lô hội), thạch chanh dây, thạch cafe, thạch trà xanh, </span></li>\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Thạch khoai môn, thạch táo, thạch kiwi, thạch yogurt, thạch phúc bồn tử, thạch socola, thạch việt quất, thạch vỏ cam...</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Jelly self-made: Các loại thạch tự làm, thạch nhà làm, cách làm thạch nhà làm ngon theo phong cách mới trà sữa nhà làm.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Flan self-made: Các loại bánh Flan tự làm.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Flan made from powder: Cách làm Flan từ bột.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch phô mát;</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch khúc bạch;</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch củ năng;</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch củ môn;</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch bắp;</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch trứng, thạch bi....</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thủy tinh các loại</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Các loại hạt đặc biệt: 3Q và Agar.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch bánh lăng.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thạch dẻo, thạch dừa...</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Trân châu theo phong cách Đài Loan, trân châu theo phong cách Thái Lan, Việt Nam.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Peach Tea: Trà đào các loại.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Shake Drinks (Thức uống lắc):</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Milk Shake ( Sữa lắc)</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Yo Shake ( Sữa chua lắc)</span></li>\n</ul></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff0000;&#34;>Phần 3</span>: <span style=&#34;color:#000000;&#34;>Tính giá gốc và lên menu.</span></span><br /><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Hướng dẫn tính giá gốc nguyên liệu từng loại đồ uống.</span><br /><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Hướng dẫn lên menu từng loại đồ uống.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff0000;&#34;>Phần 4</span>: <span style=&#34;color:#000000;&#34;>Dự tính lãi lỗ khi kinh doanh.</span></span><br /><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Bài toán về kế hoạch kinh doanh sắp tới, chi phí đầu tư ban đầu, chi phí hàng tháng, doanh số dự tính, lãi hay lỗ ước tính.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong>3. Thời gian học: </strong></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Khóa học Trà Sữa Cao Cấp: Dành cho anh chị đã có quán học cập nhật món mới: 6 buổi ( 18 tiếng ) =&gt; <span style=&#34;color:#0000ff;&#34;><a title=&#34;Chuong trinh hoc pha che 1&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-ngon-34.html&#34; target=&#34;_blank&#34;><span style=&#34;color:#0000ff;&#34;>Xem chi tiết chương trình học</span></a></span></span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Khóa học Trà Sữa Chuyên Nghiệp: Dành cho anh chị chưa biết gì về pha chế, học từ cơ bản lên chuyên nghiệp: 10 buổi ( 30 tiếng ) =&gt; <span style=&#34;color:#0000ff;&#34;><a title=&#34;Chuong trinh hoc pha che 1&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-ngon-34.html&#34; target=&#34;_blank&#34;><span style=&#34;color:#0000ff;&#34;>Xem chi tiết chương trình học</span></a></span></span></p>\n<p style=&#34;text-align:left;&#34;> </p>\n</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong>4. Giáo viên giảng dạy chính:</strong> </span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thầy Lê Hữu Trí chuyên phụ trách khu vực phía Nam.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>Thầy Đức Anh chuyên phụ trách khu vực phía Bắc.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:justify;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Là chuyên gia pha chế trà sữa với nhiều năm kinh nghiệm trong kinh doanh trà sữa và hơn 7 năm kinh nghiệm đào tạo pha chế trà sữa cho hơn 3000 quán trà sữa trên toàn quốc, hiện nay Thầy nổi tiếng là chuyên gia cố vấn cho các quán trà sữa tại TPHCM và nhiều tỉnh thành lân cận. Không những là người Thầy nhiệt huyết với học viên trên con đường giảng dạy được nhiều học viên chủ quán trà sữa yêu mến kính trọng, Thầy còn là giám đốc điều hành - CEO của Công ty TNHH Vua An Toàn. Với tinh thần học hỏi và nghiên cứu phát triển ngành pha chế kinh doanh trà sữa ở Việt Nam nói riêng và quốc tế nói chung, Thầy đã cho ra nhiều mẫu trà sữa phù hợp với từng mô hình quán từ bình dân đến cao cấp sang trọng và hiện đại đặc biệt thầy còn nghiên cứu trà sữa cho nhiều thương hiệu trà sữa ở Việt Nam. Là người tiên phong đào tạo pha chế kinh doanh trà sữa ở Việt Nam thầy Lê Hữu Trí đã truyền lại nhiều kinh nghiệm giảng dạy cho những anh chị giảng dạy trà sữa hiện nay trên thị trường.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong>5. Học phí:</strong> </span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Khóa học Trà Sữa Cao Cấp: 3.900.000 đồng.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Khóa học Trà Sữa Chuyên Nghiệp: 9.500.000 đồng.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Khóa học bí quyết trà sữa khác biệt: 22.900.000 đồng.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>(Đã bao gồm giáo trình và chi phí nguyên liệu thực hành không phát sinh thêm).</span></p>\n</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong>6. Bằng Cấp:</strong>    Học viên sau khi hoàn thành khóa học được cấp chứng nhận hoàn thành khóa học.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:center;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;hoc pha che tra sua chung nhan&#34; href=&#34;http://phache.com.vn/upload/image/mau-giay-chung-nhan.jpg&#34;><span style=&#34;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/nguyen-thi-dieu-huyen.jpg&#34; alt=&#34;cap bang hoc pha che tra sua&#34; width=&#34;600&#34; /><br /></span></a><span style=&#34;font-size:10pt;&#34;><em>Giấy chứng nhận mẫu</em></span></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;padding-top:10px;padding-bottom:10px;margin-left:0px;margin-right:0px;text-align:left;&#34;><span style=&#34;color:#000000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong>7. Lịch khai giảng khóa học: </strong></span></div>\n</div>\n<div style=&#34;text-align:justify;&#34;>\n<div class=&#34;wcustomhtml&#34; style=&#34;width:100%;&#34; align=&#34;left&#34;>\n<div style=&#34;background-color:#499413;padding:10px;&#34; align=&#34;center&#34;>\n<p style=&#34;color:#fcfcfc;font-size:23px;font-family:Arial;font-weight:bold;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;Lịch khai giảng khóa học mới&#34; href=&#34;http://phache.com.vn/lich-khai-giang/khai-giang-khoa-hoc-pha-che-tai-tphcm-38.html&#34;>XEM LỊCH HỌC PHA CHẾ THÁNG NÀY</a></span></p>\n</div>\n</div>\n</div>\n<div class=&#34;paragraph&#34; style=&#34;text-align:justify;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;day pha che tra sua&#34; href=&#34;http://phache.com.vn/thu-vien.html&#34;> </a></span></div>\n<div class=&#34;paragraph&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div class=&#34;paragraph&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-11-nam-2016-1-jpg_1.png&#34; alt=&#34;lich hoc pha che thang 10 nam 2016&#34; width=&#34;700&#34; /></span></div>\n<div class=&#34;paragraph&#34;><span style=&#34;font-size:14pt;&#34;> </span></div>\n<div class=&#34;paragraph&#34; style=&#34;text-align:justify;&#34;>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;&#34;><em><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;font-size:12pt;&#34;>lịch học tháng 10 năm 2016</span> </span></em></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p><span style=&#34;color:#0000ff;font-size:14pt;&#34;><span style=&#34;color:#000000;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;>LIÊN KẾT FACEBOOK VỚI CÁC ANH CHỊ ĐÃ VÀ ĐANG HỌC PHA CHẾ ĐỂ CÓ THÊM KIẾN THỨC:</span></span><a href=&#34;https://www.facebook.com/DayPhaCheTraSuaTranChau/?fref=ts&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> </span></a><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;FACEBOOK LỚP HỌC TRÀ SỮA&#34; href=&#34;https://www.facebook.com/DayPhaCheTraSuaTranChau/?fref=ts&#34; target=&#34;_blank&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://www.phache.com.vn/upload/image/facebook_home_logo_580-100034106-large.jpg&#34; alt=&#34;FACEBOOK TRA SUA&#34; width=&#34;200&#34; /></a></span></span></p>\n<p style=&#34;text-align:center;&#34;> <a href=&#34;https://www.facebook.com/DayPhaCheTraSuaTranChau/?fref=ts&#34;>BẤM VÀO ĐÂY</a></p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;khoa hoc pha che tra sua ngon&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-34.html&#34;><img src=&#34;http://phache.com.vn/upload/image/link-day-pha-che-tra-sua_4.png&#34; alt=&#34;lam tra sua&#34; width=&#34;1000&#34; height=&#34;50&#34; /></a></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;lop pha che cafe chuyen nghiep&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-cafe-take-away-smoothies-bartender-37.html&#34;><img src=&#34;http://phache.com.vn/upload/image/lop-hoc-cafe.png&#34; alt=&#34;lop pha che cafe&#34; width=&#34;1000&#34; height=&#34;50&#34; /></a> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;lop hoc lam kem ngon chuyen nghiep&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-hoc-cach-lam-kem-ngon-63.html&#34;><img src=&#34;http://phache.com.vn/upload/image/day-lam-kem.png&#34; alt=&#34;lop lam kem ngon&#34; width=&#34;1000&#34; height=&#34;50&#34; /></a></span></p>\n</div>\n<div class=&#34;paragraph&#34; style=&#34;text-align:center;&#34;>\n<div class=&#34;paragraph&#34; style=&#34;text-align:justify;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;day pha che tra sua&#34; href=&#34;http://phache.com.vn/thu-vien.html&#34;>  </a></span></div>\n<div class=&#34;paragraph&#34; style=&#34;text-align:justify;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div class=&#34;paragraph&#34;><span style=&#34;font-size:14pt;color:#ff0000;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;day pha che tra sua&#34; href=&#34;http://phache.com.vn/thu-vien.html&#34;><span style=&#34;color:#ff0000;&#34;>TRUNG TÂM DẠY NGHỀ PASSION LINK</span></a></span></div>\n<div class=&#34;paragraph&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div class=&#34;paragraph&#34;><span style=&#34;color:#008000;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Liên kết đam mê - Đi đến thành công!</span></div>\n</div>','Khóa học dạy pha chế trà sữa ngon - trà Thái  được trang bị đầy đủ kiến thức về nguồn gốc trà sữa, bản chất thức uống trà sữa, cách pha chế trà sữa ngon chinh phục người tiêu dùng, hướng dẫn tình hình kinh doanh trà sữa, hoạch tính chi phí kinh doanh dự tính doanh thu lãi lỗ, Nhằm giúp cho học viên có một nền tảng tốt về lĩnh vực pha chế và kinh doanh trà sữa trong mọi mô hình quán từ quán nhỏ đến quán lớn. Đến với trung tâm AZ chúng tôi Học viên sẽ được đào tạo những kiến thức căn bản về các loại thức uống thông dụng, thuật ngữ tiếng anh chuyên ngành pha chế thức uống và kỹ năng nghiệp vụ pha chế thức uống,  pha chế trên 50 loại cocktail phổ biến và có thể làm việc tại quầy bar, nhà hàng, …','day pha che, day pha che tra sua, hoc pha che tra sua, day lam tra sua, day pha tra sua, day pha che cafe take away, day pha che ruou, day pha che batender, day pha che tra sua ngon, cach pha che tra sua ngon, cach lam tra sua, day pha che tra sua mo quan, day pha tra sua ngon, day tra sua mo quan, cach mo quan tra sua, cach pha tra sua ngon, hoc tra sua o dau, hoc tra sua mo quan, day hoc tra sua, cong thuc pha tra sua, bi quyet pha tra sua ngon','tra-sua-1-copy.jpg','tra-sua-1-copy_1.jpg',1407918323,1491362206,59007,'',3),(37,'','',22,'DẠY PHA CHẾ CAFE ĐÁ XAY KEM - CAFE TAKE AWAY - SMOOTHIES KEM - BARISTA CHUYÊN NGHIỆP','<div>\n<div class=&#34;wcustomhtml&#34; style=&#34;width:100%;&#34; align=&#34;left&#34;>\n<div style=&#34;background-color:#499413;padding:10px;&#34; align=&#34;center&#34;>\n<p style=&#34;color:#fcfcfc;font-size:23px;font-family:Arial;font-weight:bold;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>KHÓA DẠY HỌC PHA CHẾ CAFE TAKE AWAY - BARISTA COFFEE</span></p>\n</div>\n</div>\n</div>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;> </span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><strong>1. Muc tiêu:</strong> Trang bị dạy pha chế cho học viên các kiến thức sau:</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Nguyên liệu trong pha chế các món cafe take away.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Dụng cụ pha chế kinh doanh cafe take away.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Công thức pha chế các loại cafe, các loại cookies đá xay, matcha đá xay, chocolate xay, các món đá xay đặc biệt, soda ý.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Cách lên menu quán.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Tình hình kinh doanh trà sữa hiện tại.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Hướng dẫn kinh doanh như hoạch định chi phí, dự tính lãi lỗ.</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/quay-arlon2.jpg&#34; alt=&#34;&#34; width=&#34;600&#34; height=&#34;423&#34; /><span style=&#34;font-size:12pt;&#34;><em>Một quầy pha chế được thiết kế đẹp</em></span></span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><strong>2. Nội dung khóa học:</strong></span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Phần 1: Tìm hiểu về dụng cụ và nguyên liệu dùng trong quán cafe take away để pha chế các loại thức uống.</span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Giới thiệu các dụng cụ cần thiết trong một quán cafe take away.</span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Giới thiệu về nguyên liệu dùng trong pha chế các loại đồ uống của quán cafe take away. Từ nguyên liệu cao cấp, chất lượng tốt, giá cả tốt dùng trong các quán cafe lớn và những loại nguyên liệu giá thấp bình dân phù hợp cho kinh doanh nhỏ giá thấp.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/tttttt_1.jpg&#34; alt=&#34;lop da xay kem ngon&#34; width=&#34;600&#34; height=&#34;800&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;color:#000000;&#34;><em>Việt quất đá xay kem ngon</em></span></p>\n<p style=&#34;text-align:left;&#34;><strong><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Phần 2: Học pha chế các loại đồ uống.</span></strong><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Lý thuyết về các công thức pha chế: làm kem, cafe đá xay, cookies đá xay, matcha đá xay, chocolate đá xay, các món đá xay đặc biệt, soda ý.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Thực hành:</span></p>\n<ul><li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Làm kem trang trí;</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Cookies đá xay các loại;</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Cafe đá xay các loại;</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Matcha các loại;</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Chocolate đá xay các loại;</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Các món đá xay ngon đặc biệt;</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Soda ý.</span></li>\n</ul><p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#0000ff;&#34;>Ice blended Cream ( Đá xay kem):</span></p>\n<ul><li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Coffee Ice Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Coffee Caramel Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Coffee Hazenut Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mocha Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Coffee Passion Link Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Chocolate Ice Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Chocolate Mint Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Chocolate Caramel Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Chocolate Hazenut Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Chocolate Coffee Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Chocolate Cookies Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Ice Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Hazenut Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Caramel Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Strawberry Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Rasperry Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Blueberry Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Cookies Mint Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Vanila Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Caramel Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Macadamia Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Amaretto Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Tiramisu Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Matcha Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Yogurt Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Yogurt Strawberry Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Yogurt Kiwi Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>Yogurt Rasperry Blended</span></li>\n<li style=&#34;text-align:left;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;> Yogurt Blueberry Blended</span></li>\n</ul><p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Phần 3: Tính giá gốc và lên menu.</span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Hướng dẫn tính giá gốc nguyên liệu từng loại đồ uống.</span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Hướng dẫn lên menu từng loại đồ uống.</span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Phần 4: Dự tính lãi lỗ khi kinh doanh.</span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>- Bài toán về kế hoạch kinh doanh sắp tới, chi phí đầu tư ban đầu, chi phí hàng tháng, doanh số dự tính, lãi hay lỗ ước tính.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><strong>3. Thời gian học: </strong></span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Lớp cấp tốc: 2 buổi</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Lớp chuyên nghiệp: 6 buổi</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Lớp chuyên nghiệp thực nghiệm tại quán: 10 buổi tại trường và 12 buổi tại quán.</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><strong>4. Học phí:</strong> </span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Lớp cao cấp: 4.500.000 VNĐ</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;> (đã bao gồm giáo trình và chi phí nguyên liệu thực hành không phát sinh thêm).</span></p>\n<p style=&#34;text-align:left;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><strong>5. Bằng Cấp:</strong>    Học viên sau khi hoàn thành khóa học được cấp chứng nhận hoàn thành khóa học.</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/da-xay.jpg&#34; alt=&#34;BANG PHA CHE CAFE&#34; width=&#34;600&#34; /></span><br /><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;color:#000000;&#34;><em>Giấy chứng nhận mẫu</em></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;>DẠY NGHỀ PASSION LINK</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;> </span></p>','Dạy pha chế barista chuyên nghiệp cafe đá xay kem, rượu, bartender chuyên nghiệp để mở quán cao cấp hay đi làm ở các quán cao cấp lương cao tại PASSION LINK. Cà phê mang đi đang trên sàn phát trển đỉnh điểm, đắp ứng nhu cầu sử dụng các món ngon trong cafe- take away nhiều quán ra đời. Để mang đến cho người tiêu dùng những món ngon trong day pha chế, học viên cần tìm hiểu và trang bị cho mình một kiến thức về các món thức uống đặc trưng về lĩnh vực này. Học viên sẽ được học đầy đủ  về nguyên liệu cần có, Công Ty Vua An Toàn cung ứng nguyên liệu tốt đảm bảo chất lượng, dụng cụ dạy pha chế cần có, các cách pha chế thức uống ngon để chinh phục người tiêu dùng.Đến với  TRUNG TÂM DẠY NGHỀ PASSION LINK học viên được trang bị kiến thức vững chắc sau khi ra mở quán.','day pha che barista, day pha che cafe da xay, day pha che smoothies, day pha che cafe take away, day pha che cookies, day pha soda y, day da xay kem, day cafe da xay, day pha cafe, day pha che cafe, day pha che coffee, day pha che barista chuyen nghiep, day pha cafe latte, day pha cafe capuchino, day pha matcha latte, day pha cafe rang xay, day pha cafe nguyet chat, day pha cafe bang may, day pha cafe ngon, hoc pha cafe o dau ngon, hoc pha che cafe o dau ngon','cafe-da-xay-copy.png','hinh2-copy.jpg',1432547381,1491361785,8972,'',2),(97,'','',24,'Những điều cần lưu ý khi mở quán trà sữa','<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><span style=&#34;color:#ff0000;&#34;>Những điều cần lưu ý khi mở quán trà sữa</span> - Hầu hết những chủ doanh nghiệp khi bước vào kinh doanh mở quán trà sữa đều lúng túng rất nhiều vấn đề liên quan đến mở quán trà sữa. Họ thường gặp phải rất nhiều vấn đề từ khâu xây dựng quán cho đến đào tạo nhân viên và các chiến lược hoạt động thành công của một quán trà sữa. Và các vấn đề khác như cơ quan nhà nước cách thức đăng ký an toàn vệ sinh thực phẩm...Rất nhiều vấn đề quan trọng mà một chủ doanh nghiệp kinh doanh trà sữa nên biết.</span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/loptrasuacaocappassionlink.jpg&#34; alt=&#34;&#34; width=&#34;600&#34; /></span></p>\r\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;color:#000000;&#34;><em>Lớp học trà sữa mở quán cao cấp ngày 28/10/2016</em></span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><span style=&#34;color:#ff0000;&#34;>Kinh doanh trà sữa</span> - Đầu tiên chúng ta cần biết chung ta đang kinh doanh lĩnh vực trà sữa là lĩnh vực trong ngành đồ ăn và thức uống kèm giải trí. Do đó khi kinh doanh mô hinh này chúng ta cần đặt ra các câu hỏi như:</span></p>\r\n<ul><li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Vì sao lại kinh doanh trà sữa?</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Kinh doanh trà sữa cần bao nhiêu vốn?</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mở quán trà sữa có lợi nhuận không?</span></li>\r\n</ul><p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Đó là các câu hỏi chúng ta cần đặt ra khi nghiên cứu về mở quán trà sữa. Hầu hết mọi chủ quán đều nghiên cứu hời hợt và không có kế hoạch cụ thể không biết khả năng thu hồi vốn có khả quan không. Họ làm một cách lựa chọn sự may mắn và tin vào năng lực bản thân, thiếu kỹ năng hoạch định. Do đó không ít chủ quán rơi vào tình trạng kinh doanh không hiệu quả phải sang quán trà sữa.</span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><span style=&#34;color:#ff0000;&#34;>Có nên mở quán trà sữa?</span> Là câu hỏi tương tự như câu hỏi số một ở trên, Bạn nên đặt ra càng nhiều câu trà lời càng tốt. Đại loại nhiều người trà lời như sau:</span></p>\r\n<ul><li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mở quán trà sữa vì đam mê.</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mở quán trà sữa vì đầu tư ít vốn.</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mở quán trà sữa vì nhà gần trường học.</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mở quán trà sữa vì muốn có việc làm khỏi đi làm thuê.</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Mở quán trà sữa vì nhà đang bán cafe.</span></li>\r\n<li><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Và nhiều câu trả lời khác.</span></li>\r\n</ul><p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;> Bạn đang thuộc nhóm có câu trả lời nào trong mở quán trà sữa? Bạn thấy đấy hầu hết các chủ quán trà sữa đều là những người mới vào nghề kinh doanh ngoài vấn đề muốn có một việc làm để kiếm thu nhập thì họ cũng muốn tự kinh doanh chứ không muốn lao động làm thuê. Một số chủ quán rất ít là những thương gia đã có nhiều kinh nghiệp trong kinh doanh các lĩnh vực khác. Nên họ rất nhạy bén khi bước vào ngành mới.</span></p>\r\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><iframe src=&#34;//www.youtube.com/embed/GeROQHr7Mxo&#34; width=&#34;600&#34; height=&#34;350&#34;></iframe></span></p>\r\n<p style=&#34;text-align:center;&#34;><em>video lớp học mở quán trà sữa</em></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;><span style=&#34;color:#ff0000;&#34;>Mở quán trà sữa cần bao nhiêu vốn?</span> Là câu hỏi quan trọng mà nhiều anh chị quan tâm khi mở quán. Để trả lời cho câu hỏi này bạn cần quay lại hỏi mình có khả năng đầu tư bao nhiêu? Và đầu tư với số vốn như vậy có khả quan hay không?</span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Vốn mở quán trà sữa dựa trên các vấn đề như mô hình quán bạn mong muốn. Hãy nhanh tay vẽ ngay một mô hình trên giấy khi có ý tưởng kinh doanh. Mô hình quán trà sữa lớn hay nhỏ. Hãy thiết kế ngay một file hình hoặc tham khảo các mô hình trà sữa lớn nhỏ. Sau khi có mô hình trà sữa bạn hãy tự mình nghiên cứu các vật tư để mở quán và tổng các chi phí đó lại trên giấy. Bạn sẽ biết kết quả của chi phí đầu tư ban đầu của quán trà sữa theo mô hình của mình.</span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Hãy dành thời gian để nghiên cứu nhiều về kinh doanh trà sữa!</span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;>Hãy xem tiếp bài viết tiếp theo tại: https://dayphachetrasuangon.blogspot.com/</span></p>\r\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:14pt;color:#000000;&#34;> </span></p>','Những điều cần lưu ý khi mở quán trà sữa','luu y khi mo quan tra sua, mo quan tra sua, kinh doanh tra sua, cach mo quan tra sua, lam sao mo quan tra sua, hoc mo quan tra sua, day mo quan tra sua','loptrasuacaocappassionlink.jpg','loptrasuacaocappassionlink_1.jpg',1476014766,1494823306,549,'',38),(38,'','',23,'KHAI GIẢNG KHÓA HỌC PHA CHẾ TẠI TPHCM','<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;>Lịch khai giảng dạy pha chế tại Trung tâm dạy nghề mở quán Passion Link, Lịch học pha chế cafe take away, Lịch khai giảng khóa học pha chế sinh tố nước ép tại TPHCM:</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;>Liên hệ: 0908.924.460 anh Phong</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:16px;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-5-2017.jpg&#34; alt=&#34;lich hoc passion link tháng 5 2017&#34; width=&#34;600&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:10pt;&#34;><em>Lịch học tháng 5 2017</em></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-4.jpg&#34; alt=&#34;&#34; width=&#34;600&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;>Lịch học pha chế tháng 04 năm 2017</span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-03-2017.png&#34; alt=&#34;&#34; width=&#34;610&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;>Lịch học tháng 03 năm 2017</span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-02-2017.png&#34; alt=&#34;&#34; width=&#34;600&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;>Lịch học tháng 02 năm 2017</span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-01-2017.png&#34; alt=&#34;&#34; width=&#34;600&#34; height=&#34;930&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><em><span style=&#34;font-size:10pt;color:#000000;&#34;>Lịch học tháng 1 năm 2017</span></em></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-pha-che-thang-12.png&#34; alt=&#34;&#34; width=&#34;600&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;>Lịch học tháng 12 năm 2016</span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-11-nam-2016-1-jpg.png&#34; alt=&#34;&#34; width=&#34;771&#34; height=&#34;1133&#34; /><br /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;color:#000000;&#34;><em>Lịch học pha chế tháng 11 năm 2016</em></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t10_1.png&#34; alt=&#34;lich hoc thang 10 2016 passion link&#34; width=&#34;700&#34; /></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:16px;&#34;><span style=&#34;font-size:10pt;&#34;><em>lịch học pha chế tháng 10 năm 2016</em></span></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:16px;&#34;><strong> </strong></span></p>\n<p style=&#34;text-align:center;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t9.png&#34; alt=&#34;LICH HOC T9&#34; width=&#34;700&#34; /></p>\n<p style=&#34;text-align:center;&#34;><em>Lich hoc pha che thang 9 Pasion Link</em></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;&#34;><strong>LỊCH HỌC THÁNG 8</strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:14pt;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t8.png&#34; alt=&#34;lịch học pha chế tháng 8&#34; width=&#34;700&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><em>lịch học pha chế tháng 8 năm 2016</em></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#000000;&#34;>LỊCH HỌC PHA CHẾ THÁNG 7</span></p>\n<p style=&#34;text-align:center;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t7_1.jpg&#34; alt=&#34;&#34; width=&#34;700&#34; /> </p>\n<p style=&#34;text-align:center;&#34;><em>lich học pha chế tháng 7</em></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#000000;&#34;><strong><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;font-size:18.6667px;&#34;>LỊCH HỌC THÁNG 6 NĂM 2016</span></span></strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#000000;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;font-size:18.6667px;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t62.jpg&#34; alt=&#34;LICH HOC THANG 6 2&#34; width=&#34;700&#34; /></span></span></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:10pt;&#34;><em><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;>lịch học bổ sung tháng 6</span></em></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:10pt;&#34;><em><span style=&#34;color:#000000;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t6.png&#34; alt=&#34;Lịch học pha chế tháng 6&#34; width=&#34;700&#34; /></span><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><br /></span></span></em></span></p>\n<p style=&#34;text-align:center;&#34;><em><span style=&#34;font-size:12pt;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;>Lịch học tháng 6 năm 2016</span></span></em></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><strong><span style=&#34;font-size:14pt;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;background-color:#ffffff;&#34;>LỚP HỌC PHA CHẾ THÁNG 4 NĂM 2016</span></span></strong></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;background-color:#ffffff;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t4.png&#34; alt=&#34;lich hoc pha che thang 4 nam 2016&#34; width=&#34;700&#34; /></span></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;&#34;><em><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;background-color:#ffffff;&#34;>Lịch học tháng 4 tại Passion Link TPHCM</span></em></span></p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;&#34;><strong>LỚP HỌC PHA CHẾ THÁNG 3 NĂM 2016</strong></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t3-2016-copy.jpg&#34; alt=&#34;&#34; width=&#34;718&#34; height=&#34;935&#34; /></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;>LỚP HỌC PHA CHẾ THÁNG 1 NĂM 2016</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-t1-2016-1.jpg&#34; alt=&#34;Lịch học pha chế năm 2016&#34; width=&#34;710&#34; height=&#34;941&#34; /><em><span style=&#34;font-size:12pt;&#34;>Lịch học khóa 1</span></em></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><em><span style=&#34;font-size:12pt;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t1-2016-2.jpg&#34; alt=&#34;lich hoc pha che&#34; width=&#34;714&#34; height=&#34;929&#34; /></span></em></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:12pt;&#34;><em><span style=&#34;color:#0000ff;font-family:&#39;times new roman&#39;, times;&#34;>Lịch học khóa 2</span></em></span></p>\n<p> </p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;font-size:18.6667px;&#34;>LỚP HỌC PHA CHẾ THÁNG 12</span></span></p>\n<p style=&#34;text-align:center;&#34;> <strong><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-t12_1.jpg&#34; alt=&#34;lịch học tháng 12&#34; width=&#34;710&#34; height=&#34;532&#34; /></span></strong></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;>LỊCH HỌC PHA CHẾ THÁNG 11</span></p>\n<p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-t11.png&#34; alt=&#34;HOC PHA CHE THANG 11&#34; width=&#34;773&#34; height=&#34;585&#34; /></span></p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-t10.png&#34; alt=&#34;lop hoc pha che thang 10&#34; width=&#34;768&#34; height=&#34;603&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><strong><em><span style=&#34;font-size:12pt;&#34;>Lớp học pha chế tháng 10</span></em></strong></span></p>\n<p style=&#34;text-align:center;&#34;>  </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-t92015.png&#34; alt=&#34;lop hoc pha che thang 9&#34; width=&#34;772&#34; height=&#34;579&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;><strong><em><span style=&#34;font-size:12pt;&#34;>Lớp học pha chế tháng 9</span></em></strong><br /></span></p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><a title=&#34;day pha che tra sua&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc/day-pha-che-tra-sua-tran-chau-34.html&#34;><img src=&#34;http://phache.com.vn/upload/image/lich-hoc-thang-6.png&#34; alt=&#34;&#34; width=&#34;748&#34; height=&#34;520&#34; /></a></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:18pt;font-family:&#39;times new roman&#39;, times;&#34;>Lịch học tại TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span> tháng 8 năm 2015</span></p>\n<p style=&#34;text-align:center;&#34;> <img src=&#34;http://phache.com.vn/upload/image/lich-khai-giang-thang-7_1.jpg&#34; alt=&#34;lich hoc tai az drinks&#34; width=&#34;780&#34; height=&#34;539&#34; /></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-size:18pt;font-family:&#39;times new roman&#39;, times;&#34;>Lịch học tại TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span> tháng 7 năm 2015</span></p>\n<p style=&#34;text-align:center;&#34;><img src=&#34;http://phache.com.vn/upload/image/khai-giang-thang8-copy.jpg&#34; alt=&#34;&#34; width=&#34;775&#34; height=&#34;469&#34; /></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:18pt;font-family:&#39;times new roman&#39;, times;color:#0000ff;&#34;>TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span> - tháng 8 năm 2015</span></p>\n<p style=&#34;text-align:center;&#34;> </p>','Khai giảng lớp học pha chế trà sữa tại tphcm','dạy pha chế trà sữa tại tphcm, dạy pha chế trà sữa, dạy pha chế trà sữa trà sữa tại hcm','lop-hoc-pha-che-2_1.png','lop-hoc-pha-che-2.png',1432747215,1493690401,6864,'',4),(39,'','',23,'Lịch Khai Giảng Khóa Học Pha Chế Tại Hà Nội','<p><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/khai-giang-thang8-copy.jpg&#34; alt=&#34;&#34; width=&#34;775&#34; height=&#34;469&#34; /></p>','Khai giảng lớp pha chế trà sữa tại Hà Nội','Lớp học  pha chế trà sữa tại Hà nội, học pha chế hà nội, dạy pha chế trà sữa tại hà nội','khai-giang-pha-che-tra-sua.jpg','khai-giang-pha-che-tra-sua_1.jpg',1432748027,1457178265,2097,'',3),(40,'','',23,'Dự Kiến Ngày Khai Giảng Pha chế Tại Đà Nẵng','<p>Thông tin đang được cập nhât,...</p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><strong><span style=&#34;color:#008000;&#34;>TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></span></strong></p>','Khóa học pha chế tại Đà Nẵng','Trung tâm đào tạo pha chế trà sữa TRƯỜNG DẠY NGHỀ PASSION LINK, chuyên đào tạo pha chế trà sữa khắp nơi mọi miền trên đất nước','pha-che-tra-sua-da-nang_2.png','pha-che-tra-sua-da-nang_3.png',1433352485,1457178227,2153,'',2),(41,'','',23,'Nhận Dạy Pha Chế Tại Quán','<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-size:24pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;DAY PHA CHE&#34; href=&#34;http://phache.com.vn/&#34;>   DẠY PHA CHE</a><br /></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:justify;&#34;><span style=&#34;color:#0000ff;&#34;>Khóa học dạy pha chế trà sữa được trang bị đầy đủ kiến thức về nguồn gốc trà sữa, bản chất thức uống trà sữa, cách pha chế trà sữa ngon chinh phục người tiêu dùng, hướng dẫn tình hình kinh doanh trà sữa, hoạch tính chi phí kinh doanh dự tính doanh thu lãi lỗ, Nhằm giúp cho học viên có một nền tảng tốt về lĩnh vực pha chế và kinh doanh trà sữa trong mọi mô hình quán từ quán nhỏ đến quán lớn.</span></p>\n<p style=&#34;text-align:justify;&#34;> </p>\n<p style=&#34;text-align:justify;&#34;><span style=&#34;color:#0000ff;&#34;><img src=&#34;http://phache.com.vn/upload/image/gggggg.jpg&#34; alt=&#34;day pha che&#34; width=&#34;920&#34; height=&#34;690&#34; /></span></p>\n<p style=&#34;text-align:justify;&#34;><img src=&#34;http://phache.com.vn/upload/image/hihhnhhn.jpg&#34; alt=&#34;day pha che&#34; width=&#34;920&#34; height=&#34;920&#34; /></p>\n<p style=&#34;text-align:center;&#34;><strong><span style=&#34;color:#008000;&#34;>TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></span></strong></p>','Nhập dạy pha chế trà sữa tại nhà','TRƯỜNG DẠY NGHỀ PASSION LINK chuyên dạy pha chế tại nhà, dạy pha chế tại quán','phachecooktail.jpg','phachecooktail_1.jpg',1433353435,1457178197,2251,'',1),(45,'','',24,'Dạy pha chế trà sữa ở đâu uy tín?','<p style=&#34;text-align:justify;&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Dạy pha chế trà sữa uy tín do trung tâm đào tạo pha chế <strong><span style=&#34;color:#008000;&#34;><span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></span></strong> với kinh nghiệm nhiều năm trong ngành  . Sẽ giúp các học viện nhiều kiến thức và trang bị cho minh khi mở quán và công ty cung cấp nguyên liệu cho quý khách.</span></p>\n<p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/tttttt.jpg&#34; alt=&#34;day pha che&#34; width=&#34;450&#34; /></span></p>\n<p style=&#34;text-align:justify;&#34;> </p>\n<p style=&#34;text-align:justify;&#34;><strong><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;background-color:#00ff00;&#34;>Mục tiêu khóa học:</span></strong></p>\n<ul><li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#008000;&#34;> Trong quá trình dạy, thực hành nhiều lần cho học viên có kĩ năng thao tác nhanh nhất.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#008000;&#34;>Phát huy khả năng sáng tạo của bản thân.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#008000;&#34;> Khi kết thúc khoá học, học viên có kiến thức về mô hình take away. Hơn thế, học viên sẽ có kĩ năng thao tác pha chế nhanh nhẹn, có tất cả các kiến thức về cách pha chế mọi thức uống take away.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;color:#008000;&#34;>Cung cấp nơi mua nguyên vật liệu giá rẻ nhất thị trường.</span></li>\n<li></li>\n<li><img src=&#34;http://phache.com.vn/upload/image/day13456.jpg&#34; alt=&#34;day pha che&#34; width=&#34;720&#34; height=&#34;720&#34; /><br /><br /><strong><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;background-color:#00ff00;&#34;>II. Nội dung khóa học pha chế:</span></strong></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Chia sẻ các công thức bí kíp của quán. </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Lý thuyết về cafe, xu hướng phát triển cafe trên thế giới và Việt Nam. </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Pha chế các loại đá xay (cà phê đá xay, cookies, chocolate, smoothies, yaourt, các loại soda…) và các món cà phê cơ bản (espresso tiêu chuẩn, cappuccino, americano…). </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Được thực hành trên những trang thiết bị hiện đại, cao cấp.</span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Cách pha chế để tạo thức uống chất lượng cao nhất. </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> Trung Tâm cung cấp  nguyên vật liệu giá rẻ nhất. </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Cung cấp kiến thức về máy pha cafe, máy xay cafe, máy xay công nghiệp (máy xay sinh tố công suất lớn) và các trang thiết bị cho 1 quán coffee to go. </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Hướng dẫn cặn kẽ trước khi mua trang thiết bị như máy pha cafe, máy xay cafe, máy xay công nghiệp, các loại bàn ghế, tủ lạnh, tủ đông, máy tính tiền, ly, dĩa, dàn loa… </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Khi kết thúc khoá học, học viên có thể quay lại để tự pha chế món tự sáng chế. </span></li>\n<li><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Bảo đảm cho bạn về menu với nước uống chất lượng cao. </span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> Chúng tôi rất hân hạnh được hướng dẫn cho các bạn đang hoặc chuẩn bị mở quán cà phê. </span></li>\n</ul>','Dạy pha chế trà sữa uy tín do trung tâm đào tạo pha chế Az với kinh nghiệm nhiều năm trong ngành  . Sẽ giúp các học viện nhiều kiến thức và trang bị cho minh khi mở quán và công ty cung cấp nguyên liệu cho quý khách.','dạy pha che tra sua ở đau uy tin','pha1.jpg','pha12.jpg',1440172296,1457178091,1513,'11',1),(46,'','',24,'Cách pha chế trà sữa ở đâu  ngon ?','<p style=&#34;text-align:center;&#34;><span style=&#34;background-color:#ffffff;font-size:8pt;&#34;><strong><span style=&#34;color:#0000ff;&#34;>Bạn đang lo lắng học pha chế trà sữa ở đâu uy tín?</span></strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:8pt;&#34;><strong><span style=&#34;color:#0000ff;&#34;><a title=&#34;day pha che&#34; href=&#34;http://phache.com.vn/&#34;>Dạy pha chế</a> trà sữa ở đâu ngon?</span></strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#008000;font-size:8pt;&#34;><strong>Trung tâm đầu tiên dạy pha chế trà sữa tại Việt Nam <strong><span style=&#34;color:#008000;&#34;><span style=&#34;color:#ff0000;&#34;>PASSION LINK </span></span></strong>và tư vấn Mở quán!</strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:8pt;&#34;><strong><span style=&#34;color:#0000ff;&#34;>CÔNG TY TNHH VUA AN TOÀN </span></strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:8pt;&#34;><strong><span style=&#34;color:#0000ff;&#34;>    <strong><span style=&#34;color:#008000;&#34;>TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></span></strong>  </span></strong></span></p>\n<p style=&#34;text-align:justify;&#34;> </p>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;color:#0000ff;&#34;><strong>1.Mục tiêu</strong></span>: Trang bị cho học viên các kiến thức sau:</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>- Nguyên liệu pha chế trà sữa.</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>- Dụng cụ pha chế kinh doanh trà sữa.</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>- Công thức pha chế các loại trà sữa đài loan, trà sữa thái lan, hồng trà, lục trà, lipton, yo shake, milk shake, cách chế biến FLAN, rau câu phomai, nấu trân châu ngon.</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>- Cách lên menu quán.</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>- Tình hình kinh doanh trà sữa hiện tại.</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>- Hướng dẫn kinh doanh như hoạch định chi phí, dự tính lãi lỗ.</div>\n<p style=&#34;text-align:justify;&#34;> </p>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><img src=&#34;http://phache.com.vn/upload/image/quan-dep.jpg&#34; alt=&#34;hinh quan tra sua dep&#34; width=&#34;710&#34; height=&#34;473&#34; /></div>\n<p style=&#34;text-align:justify;&#34;><em>Hình quán trà sữa sang trọng bố trí đẹp và phong thủy -<span style=&#34;color:#0000ff;&#34;> dạy pha chế</span></em></p>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><strong>2. Nội dung khóa học:</strong></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>Phần 1: Tìm hiểu về dụng cụ và nguyên liệu dùng trong quán trà sữa để pha chế các loại thức uống.<br />- Giới thiệu các dụng cụ cần thiết trong một quán trà sữa.<br />- Giới thiệu về nguyên liệu dùng trong dạy pha chế các loại đồ uống của quán trà sữa. Từ nguyên liệu cao cấp, chất lượng tốt, giá cả tốt dùng trong các quán trà sữa lớn và những loại nguyên liệu giá thấp bình dân phù hợp cho kinh doanh nhỏ giá thấp.<br /><strong>Phần 2: <a href=&#34;http://phache.com.vn/&#34;>Học pha chế</a> các loại đồ uống.</strong><br />- Lý thuyết về các công thức nấu pha chế: Trân châu, bánh flan, thạch rau câu phô mai, trà sữa đài loan, trà sữa thái lan, hồng trà, lục trà, lipton, yo shake ( yagurt hương vị trái cây hấp dẫn), milk shake ( sữa lắc ).<br />- Thực hành pha chế các loại đồ uống:<br />+ Nấu trân châu;<br />+ Nấu bánh flan;<br />+ Nấu thạch rau câu phô mai;<br />+ Nấu trà sữa, pha chế các loại trà sữa;<br />+ Nấu hồng trà, pha chế các loại hồng trà;<br />+ Nấu lục trà, pha chế các loại lục trà;<br />+ Pha chế các loại lipton;<br />+ Pha chế các loại yo shake;<br />+ Pha chế các loại milk shake;<br />Phần 3: Tính giá gốc và lên menu.<br />- Hướng dẫn tính giá gốc nguyên liệu từng loại đồ uống.<br />- Hướng dẫn lên menu từng loại đồ uống.<br />Phần 4: Dự tính lãi lỗ khi kinh doanh.<br />- Bài toán về kế hoạch kinh doanh sắp tới, chi phí đầu tư ban đầu, chi phí hàng tháng, doanh số dự tính, lãi hay lỗ ước tính.</div>\n<p style=&#34;text-align:justify;&#34;> </p>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><strong>3. Thời gian học: </strong></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>\n<p>- Khóa học Trà Sữa Cao Cấp: Dành cho anh chị đã có quán học cập nhật Trà Sữa Nhà Làm: 6 buổi ( 18 tiếng ) =&gt; <a title=&#34;Chuong trinh hoc pha che 1&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-ngon-34.html&#34; target=&#34;_blank&#34;>Xem chi tiết chương trình học</a></p>\n<p>- Khóa học Trà Sữa Chuyên Nghiệp: Dành cho anh chị chưa biết gì về pha chế, học từ cơ bản lên chuyên nghiệp, học Trà Sữa Nhà Làm - Trà Sữa Rau Củ Quả Tươi: 10 buổi ( 30 tiếng ) =&gt; <a title=&#34;Chuong trinh hoc pha che 1&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-ngon-34.html&#34; target=&#34;_blank&#34;>Xem chi tiết chương trình học</a></p>\n</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><strong>4. Học phí: </strong></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;>\n<p>- Khóa học Trà Sữa Cao Cấp: 3.900.000 đồng</p>\n<p>- Khóa học Trà Sữa Chuyên Nghiệp: 9.500.000 đồng</p>\n<p>- Khóa học thực tế tại quán: 15.000.000 đồng</p>\n<p>(Đã bao gồm giáo trình và chi phí nguyên liệu thực hành không phát sinh thêm).</p>\n</div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;> </div>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;&#34;><strong><a title=&#34;D&#34; href=&#34;http://phache.com.vn/&#34;>DẠY PHA CHẾ</a> UY TÍN - AN TOÀN - CHẤT LƯỢNG CHO HỌC VIÊN TẠI TRUNG TÂM</strong></span></p>','cách dạy pha chế ở đâu ngon?','day pha che , cách dạy pha chế ở đâu ngon?','phieu-thuong-thuc-cac-loai-nuoc-uong-phong-cach-my-tai-khaisilk-thats-cafe-2-chi-29000d_1.jpg','ruouou_1.jpg',1440227606,1490583222,3058,'',3),(48,'','',24,'Dạy Pha Chế Sinh Tố','<p style=&#34;text-align:center;&#34;><strong><span style=&#34;font-size:18pt;font-family:&#39;times new roman&#39;, times;background-color:#00ff00;&#34;><a title=&#34;DAY PHA CHE&#34; href=&#34;http://phache.com.vn/day-pha-che-tra-sua-ngon/day-pha-che-sinh-to-48.html&#34;><span style=&#34;background-color:#00ff00;&#34;>DẠY PHA CHẾ THỨC UỐNG CÁC LOẠI</span></a></span></strong></p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><strong><a title=&#34;Dạy pha chế trà sữa&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-34.html&#34;>Lớp dạy học pha chế trà sữa chuyên nghiệp</a><br /></strong></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><strong><a title=&#34;dạy pha chế cafe take away&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-cafe-take-away-bartender-37.html&#34;>Lớp dạy học cách pha chế cafe take away</a></strong> </p>\n<p style=&#34;text-align:center;&#34;>Lớp dạy học cách chế biến thức ăn vặt ngon tuyệt đỉnh</p>\n<p style=&#34;text-align:center;&#34;>Chiêu sinh khóa học dạy pha chế mở quán kinh doanh trà sữa</p>\n<p style=&#34;text-align:center;&#34;>Lớp dạy học pha chế bartender chuyên nghiệp</p>\n<p style=&#34;text-align:center;&#34;>Khóa  học pha chế barista chuyên nghiệp</p>\n<p style=&#34;text-align:justify;&#34;><span style=&#34;color:#0000ff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Hiện nay có rất nhiều quán cafe  làm sinh tố các loại trái cây  nhưng không biết pha chế như thế nào cho ngon thơm và hấp dẫn . Thấu hiểu được được vấn đề đó <strong><span style=&#34;color:#008000;&#34;>TRƯỜNG DẠY NGHỀ <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></span></strong> sẽ giúp bạn có ly sinh tố đúng mùi vị và cách pha chế đúng cách để thu hút khách tại quán của bạn!</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><iframe src=&#34;//www.youtube.com/embed/GeROQHr7Mxo&#34; width=&#34;600&#34; height=&#34;350&#34;></iframe></span></p>\n<p style=&#34;text-align:justify;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/11920373_818905931559838_1982114452_n.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;450&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><img src=&#34;http://phache.com.vn/upload/image/hocvien1111.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;309&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><img src=&#34;http://phache.com.vn/upload/image/day13456_1.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;600&#34; /></p>\n<p><span style=&#34;color:#0000ff;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Lịch khai giảng dạy pha chế trà sữa <strong><span style=&#34;color:#008000;&#34;><span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></span></strong>, Lịch học pha chế cafe take away, Lịch khai giảng khóa học pha chế sinh tố nước ép tại TPHCM:</span></p>\n<p> </p>\n<p><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-t12_1.jpg&#34; alt=&#34;lich học tháng 12&#34; width=&#34;600&#34; height=&#34;450&#34; /></p>\n<p style=&#34;text-align:center;&#34;><em>Lịch học pha chế mở quán trà sữa &amp; cafe tháng 12 năm 2015</em></p>\n<p> </p>\n<p style=&#34;text-align:center;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-t11_1.png&#34; alt=&#34;lịch tháng 11&#34; width=&#34;773&#34; height=&#34;585&#34; /><em>Lịch học pha chế mở quán trà sữa &amp; cafe tháng 11 năm 2015</em></p>\n<p> </p>\n<p><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-hoc-t10.png&#34; alt=&#34;lop hoc pha che thang 10&#34; width=&#34;736&#34; height=&#34;578&#34; /></p>\n<p style=&#34;text-align:center;&#34;><em>Lịch học pha chế mở quán trà sữa &amp; cafe tháng 10 năm 2015</em></p>\n<p style=&#34;text-align:justify;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/lich-t92015.png&#34; alt=&#34;lịch học tháng 9&#34; width=&#34;772&#34; height=&#34;579&#34; /><em>Lịch học pha chế mở quán trà sữa &amp; cafe tháng 09 năm 2015</em></p>\n<p> </p>\n<p><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/