INSERT INTO `page` VALUES (3,'html',0,1,'day-pha-che',NULL,'Giới thiệu pha chế trà sữa','<p style=&#34;text-align:center;&#34;><span style=&#34;color:#000000;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><strong>CÔNG TY TNHH VUA AN TOÀN</strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><strong>TRUNG TÂM DẠY PHA CHẾ PASSION LINK ( A-Z DRINKS)</strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;>Chuyên gia Thầy Lê Hữu Trí.</span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;>Trà sữa trân châu là một loại thức uống đặc biệt du nhập vào Việt Nam và được giới trẻ yêu thích và trở nên nổi tiếng từ năm 2009. Cho đến nay trà sữa trân châu vẫn đang trên con đường phát triển từ các tỉnh thành phố lớn lan sang các thành phố nhỏ và về các vùng làng quê nông thôn Việt Nam.</span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><iframe style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;https://www.youtube.com/embed/3i6BfCyLNIM&#34; width=&#34;600&#34; height=&#34;455&#34; frameborder=&#34;0&#34;></iframe></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><a title=&#34;day pha che&#34; href=&#34;http://phache.com.vn/&#34;> </a><span style=&#34;font-size:10pt;&#34;><em>Video lớp học trà sữa tổng hợp 2013</em></span></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/menu-treo.jpg&#34; alt=&#34;AZ DRINKS&#34; width=&#34;600&#34; height=&#34;423&#34; /><span style=&#34;font-size:10pt;&#34;><em>Một quầy bar đẹp của quán trà sữa</em></span></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><strong> </strong>Để góp phần tạo nên những loại trà sữa ngon thơm ngon đậm đà, chất lượng hàng đầu và giá cả hợp lý cho các chủ quán kinh doanh phù hợp với thị hiếu của khách hàng. Trung Tâm Đào Tạo Pha Chế  Passion Link  mong muốn đem đến cho những chủ quán một sự tự tin về cách pha chế và cách điều hành kinh doanh quán trà sữa trân châu. Bên cạnh đó chung tôi tự hào tạo nên lòng tin của khách hàng dùng trà sữa trân châu được làm từ những nguyên liệu an toàn sạch xuất xứ rõ ràng. </span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;> </span></p>\n<p><iframe style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;//www.youtube.com/embed/GeROQHr7Mxo&#34; width=&#34;600&#34; height=&#34;513&#34;></iframe></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:10pt;&#34;><em>Phim lớp học pha chế tại Passion Link</em></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/phache22222.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;441&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:10pt;&#34;><em>lớp học pha chế trà sữa mở quán tháng 10/2014</em></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/phache.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;374&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:10pt;&#34;><em>lớp học pha chế trà sữa cao cấp tại Passion Link</em></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;> </span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/viueeenennn.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;450&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:10pt;&#34;><em>Mô hình quán nhỏ của học viên Cà Mau</em></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/vien.jpg&#34; alt=&#34;day pha che&#34; width=&#34;600&#34; height=&#34;309&#34; /></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:10pt;&#34;><em>Lớp học trà sữa tại Passion Link các anh chị đều đã thành công.</em></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;>Khóa học pha chế trà sữa, kinh doanh trà sữa sẽ mang đến đầy đủ kiến thức về nguồn gốc, bản chất của trà sữa, tình hình phát triển kinh doanh trà sữa hiện tại và tương lai, cách pha chế các loại thức uống trong kinh doanh trà sữa trân châu ngon chất lượng mà giá cả phù hợp cho từng mô  <span style=&#34;color:#0000ff;&#34;>hình quán nhỏ đến quán lớn.</span></span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;font-size:12pt;&#34;> </span></p>','Giới thiệu',2,'Giới thiệu trung tâm az drinks, trung tâm đào tạo pha chế trà sữa số 1 việt nam, chuyên đào tạo trà sữa Đài Loan, Hồng trà, trà sữa thái','az drinks, trung tam dao tao pha che gioi, trung tam day pha che uy tinh, trung tam day pha che noi tieng nhat, đào tạo pha chế trà sữa tại hcm, dạy pha chế trà sữa, học pha chế trà sữa',1,0),(25,'news',0,1,'mo-quan',NULL,'Mở quán kinh doanh trà sữa','','MỞ QUÁN',6,'Tài liệu hướng dẫn mở quán trà sữa hoàn thiện để hoạt động tốt ngay từ những ngày đầu, thiết kế quán trà sữa, trang trí quán trà sữa, dụng cụ máy móc pha chế trà sữa, cung cấp bàn ghế trà sữa, quầy pha chế quầy bar đẹp giá rẻ, xe bán trà sữa di động, xe đẩy bán trà sữa đẹp, các kiểu ly trà sữa độc đáo mới lạ tại TPHCM, Bình Dương, Biên Hòa, Vũng Tàu, Long An','xe tra sua, xe ban tra sua, ban ghe tra sua, quay pha che tra sua, ly tra sua, ly tra sua doc dao, thiet ke quan tra sua, trang tri quan tra sua dep, xe ban tra sua dep, xe ban tra sua doc dao, may lam lanh tra sua, may danh tra sua, may pha tra sua, dung cu pha tra sua',1,1),(10,'home',0,1,'home',NULL,'Dạy pha chế trà sữa - Rượu Các Loại','<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:24pt;font-family:&#39;times new roman&#39;, times;&#34;>Công Ty TNHH VUA AN TOÀN</span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:24pt;font-family:&#39;times new roman&#39;, times;&#34;>Trung Tâm Đào Tạo Dạy Pha Chế AZ</span></p>','Trang chủ',1,'Dạy pha chế trà sữa, dạy pha chế cafe take away, dạy pha chế barista, dạy pha chế rượu, dạy pha chế sinh tố nước ép trái cây... là một trong những chuyên ngành mà trung tâm đang đào tạo uy tín nhiều năm.','dạy pha chế, day pha chế rượu, day pha che tra sua',1,1),(15,'contact',0,1,'lien-he',NULL,'Liên hệ','<p style=&#34;text-align:center;&#34;><span style=&#34;color:#0000ff;font-size:24pt;font-family:&#39;times new roman&#39;, times;&#34;> CÔNG TY TNHH VUA AN TOÀN  </span></p>\n<p style=&#34;text-align:center;&#34;><strong><span style=&#34;font-family:&#39;times new roman&#39;, times;color:#0000ff;font-size:18pt;&#34;>   Trung Tâm Đào Tạo Dạy Pha Chế A - Z ( PASSION LINK)</span></strong> <span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;&#34;><strong>Trụ Sở chính: 180A Hoàng Hoa Thám, Phường 12, Q.Tân Bình, TPHCM. ĐT: 0862.708787</strong></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;&#34;><strong>CN1 : Nhà 10, Lô 6, Ngõ 51, Phố Lãng Yên, Q.HBT, Hà Nội. ĐT: 0919.527448</strong></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;font-size:14pt;&#34;><strong>CN2: 247 Phạm Ngủ Lão, P. Hiệp Thành, TP. Thủ Dầu Một, TPHCM. ĐT: 0987013502</strong></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#ff0000;&#34;><strong><em>Hãy liên hệ ngay với trung tâm để được tư vấn: 0907.961.607</em></strong></span></p>','Liên hệ',9,'Liên hệ trung tâm đào tạo pha chế A-Z','  day pha che, trung tam dao tao pha che tra sua',1,1),(22,'news',0,1,'cac-khoa-hoc-day-pha-che',NULL,' khóa học dạy pha chế trung tâm az','','CÁC KHÓA HỌC DẠY PHA CHẾ',2,'Những khóa học tại trung tâm az ','day pha che tra sua, day pha che cafe, khoa hoc day pha che  sinh to nuoc ep, day pha che rượu..',1,1),(23,'news',0,1,'lich-khai-giang',NULL,'Lịch khai giảng pha chế trà sữa','','LỊCH KHAI GIẢNG',3,'Lịch khai giảng khóa mới trung tâm đào tạo pha chế A-Z DRINKS, lịch khai giảng pha chế trà sữa chân trâu, pha chế rượu các loại','az drinks, trung tam day pha che az drinks, thong tin khoa moi trung tam az drinks, dạy pha chế trà sữa tại az drinks, pha chế rượu các loại',1,1),(24,'news',0,1,'day-pha-che-tra-sua-ngon',NULL,'Tin tức day pha chế tra sưa ngon','','BÍ QUYẾT HAY',2,'Các thông tin về pha chế, phát triển pha chế trà sữa, cách làm trà sữa','cach pha che tra sua ngon, huong dan pha che tra sua ngon, tin tuc ve tra sua, tra sua chat luong, nguyen lieu tra sua',1,1),(28,'elink',0,1,'http://phache.com.vn/danh-muc/tra-sua-teatri-1.html',NULL,'Trà sữa TEATRI một thương hiệu trà sữa an toàn và ngon nhất hiện nay.','<p>Quán trà sữa teatri ngon nhất hiện nay, với nhiều loại trà sữa ngon an toàn chất lượng</p>','TRÀ SỮA TEATRI',4,'Trà Sữa TeaTri là thương hiệu trà sữa sạch, an toàn và ngon nhất bổ dưỡng nhất hiện nay, với công thức do chuyên gia đào tạo pha chế trà sữa hàng đầu Việt Nam Thầy Lê Hữu Trí.','tra sua teatri, tra sua ngon nhat hien nay, cach lam tra sua ngon, bi quyet lam tra sua ngon nhat.',1,0),(29,'html',0,1,'day-pha-che-tra-sua',NULL,'','<div class=&#34;news_image_title&#34; style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> <img src=&#34;http://phache.com.vn/upload/image/index.jpg&#34; alt=&#34;&#34; width=&#34;970&#34; height=&#34;233&#34; /></span></div>\n<div class=&#34;news_image_title&#34; style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div>\n<div>\n<div class=&#34;wcustomhtml&#34; align=&#34;left&#34;>\n<div align=&#34;center&#34;>\n<div>\n<div class=&#34;wcustomhtml&#34; style=&#34;width:100%;&#34; align=&#34;left&#34;>\n<div style=&#34;background-color:#499413;padding:10px;&#34; align=&#34;center&#34;>\n<p style=&#34;color:#fcfcfc;font-size:23px;font-family:Arial;font-weight:bold;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><strong><img src=&#34;http://tuyensinh24h.com.vn/wp-content/uploads/2014/06/new.gif&#34; alt=&#34;&#34; /></strong>Khóa học dạy pha chế trà sữa - Trà Thái</span></p>\n<p><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> </span></p>\n</div>\n</div>\n</div>\n<div><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n</div>\n</div>\n</div>\n<div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff6600;&#34;><strong>1.Mục tiêu</strong>:</span>   <span style=&#34;color:#000000;&#34;>Trang bị cho học viên các kiến thức sau:</span></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Nguyên liệu pha chế trà sữa.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Dụng cụ pha chế kinh doanh trà sữa.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Công thức pha chế các loại trà sữa đài loan, trà sữa thái lan, hồng trà, lục trà, lipton, yo shake, milk shake, cách chế biến FLAN, rau câu phomai, nấu trân châu ngon.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Cách lên menu quán.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Tình hình kinh doanh trà sữa hiện tại.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;color:#000000;font-family:&#39;times new roman&#39;, times;&#34;>- Hướng dẫn kinh doanh như hoạch định chi phí, dự tính lãi lỗ.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/vien.jpg&#34; alt=&#34;&#34; width=&#34;700&#34; height=&#34;360&#34; /></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><em>Hình ảnh khóa học 58 tại trung tâm đào tạo pha chế AZ</em></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong><strong><img src=&#34;http://tuyensinh24h.com.vn/wp-content/uploads/2014/06/new.gif&#34; alt=&#34;&#34; /></strong><span style=&#34;color:#ff6600;&#34;>2. Nội dung khóa học:</span></strong></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff6600;&#34;>Phần 1</span>: Tìm hiểu về dụng cụ và nguyên liệu dùng trong quán trà sữa để pha chế các loại thức uống.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Giới thiệu các dụng cụ cần thiết trong một quán trà sữa.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Giới thiệu về nguyên liệu dùng trong pha chế các loại đồ uống của quán trà sữa. Từ nguyên liệu cao cấp, chất lượng tốt, giá cả tốt dùng trong các quán trà sữa lớn và những loại nguyên liệu giá thấp bình dân phù hợp cho kinh doanh nhỏ giá thấp.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff6600;&#34;>Phần 2</span>: Học pha chế các loại đồ uống.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Lý thuyết về các công thức nấu pha chế: Trân châu, bánh flan, thạch rau câu phô mai, trà sữa đài loan, trà sữa thái lan, hồng trà, lục trà, lipton, yo shake ( yagurt hương vị trái cây hấp dẫn), milk shake ( sữa lắc ).</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Thực hành pha chế các loại đồ uống:</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Nấu trân châu;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Nấu bánh flan;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Nấu thạch rau câu phô mai;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Nấu trà sữa, pha chế các loại trà sữa;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Nấu hồng trà, pha chế các loại hồng trà;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Nấu lục trà, pha chế các loại lục trà;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Pha chế các loại lipton;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Pha chế các loại yo shake;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>+ Pha chế các loại milk shake;</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff6600;&#34;>Phần 3</span>: Tính giá gốc và lên menu.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Hướng dẫn tính giá gốc nguyên liệu từng loại đồ uống.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Hướng dẫn lên menu từng loại đồ uống.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff6600;&#34;>Phần 4</span>: Dự tính lãi lỗ khi kinh doanh.</span><br /><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>- Bài toán về kế hoạch kinh doanh sắp tới, chi phí đầu tư ban đầu, chi phí hàng tháng, doanh số dự tính, lãi hay lỗ ước tính.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong><strong><img src=&#34;http://tuyensinh24h.com.vn/wp-content/uploads/2014/06/new.gif&#34; alt=&#34;&#34; /></strong><span style=&#34;color:#ff6600;&#34;>3. Thời gian học: </span></strong></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Lý thuyết: 4 tiết.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Thực hành: 10 tiết.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong><span style=&#34;color:#ff6600;&#34;>4. Giáo viên giảng dạy:</span> Thầy Lê Hữu Trí.</strong></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Là chuyên gia pha chế trà sữa với nhiều năm kinh nghiệm trong kinh doanh trà sữa và hơn 3 năm kinh nghiệm đào tạo pha chế trà sữa cho hơn 500 quán trà sữa trên toàn quốc, hiện nay Thầy nổi tiếng là chuyên gia cố vấn cho các quán trà sữa tại TPHCM và nhiều tỉnh thành lân cận. Không những là người Thầy nhiệt huyết với học viên trên con đường giảng dạy được nhiều học viên chủ quán trà sữa yêu mến kính trọng, Thầy còn là giám đốc điều hành - CEO của Công ty TNHH Vua An Toàn.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Với tinh thần học hỏi và nghiên cứu phát triển ngành pha chế kinh doanh trà sữa ở Việt Nam nói riêng và quốc tế nói chung, Thầy đã cho ra nhiều mẫu trà sữa phù hợp với từng mô hình quán từ bình dân đến cao cấp sang trọng, đặc biệt thầy còn nghiên cứu trà sữa cho nhiều thương hiệu trà sữa ở Việt Nam.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong><span style=&#34;color:#ff6600;&#34;>5. Học phí:</span> </strong> 1.200.000 VNĐ (đã bao gồm giáo trình và chi phí nguyên liệu thực hành không phát sinh thêm).</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><span style=&#34;color:#ff6600;&#34;><strong>6. Bằng Cấp:</strong></span>    Học viên sau khi hoàn thành khóa học được cấp chứng nhận hoàn thành khóa học.</span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34; style=&#34;text-align:center;&#34;><span style=&#34;font-family:&#39;times new roman&#39;, times;&#34;><img style=&#34;display:block;margin-left:auto;margin-right:auto;&#34; src=&#34;http://phache.com.vn/upload/image/mau-cn-tieng-viet-website-copy.png&#34; alt=&#34;cap chung nhan pha che tra sua&#34; width=&#34;490&#34; height=&#34;345&#34; /><em>Giấy chứng nhận mẫu</em></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><strong>7. Các món thông dụng lên menu sau khóa học:</strong></span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;> </span></div>\n<div class=&#34;wsite-image wsite-image-border-thin&#34;><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;>Học viên xem chi tiết tại đây</span></div>\n</div>\n<div>\n<div class=&#34;wcustomhtml&#34; align=&#34;left&#34;>\n<div align=&#34;center&#34;>\n<p><span style=&#34;font-size:14pt;font-family:&#39;times new roman&#39;, times;&#34;><a title=&#34;Hinh menu tra sua&#34; href=&#34;http://phache.com.vn/thu-vien.html&#34;>Xem mẫu menu các món thông dụng đã học</a></span></p>\n</div>\n</div>\n</div>\n</div>','DẠY PHA CHẾ TRÀ SỮA',2,'','',1,0),(30,'html',0,1,'hoc-phi',NULL,'Học phí lớp học pha chế đồ uống mở quán','<p style=&#34;text-align:center;&#34;><span style=&#34;color:#008000;&#34;><span style=&#34;font-size:16px;&#34;><strong>TRƯỜNG DẠY PHA CHẾ TRÀ SỮA <span style=&#34;color:#ff0000;&#34;>PASSION LINK</span></strong></span></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#008000;&#34;><span style=&#34;font-size:16px;&#34;><strong>TỰ TIN CHẤT LƯỢNG TRÀ SỮA NGON DẠY HỌC TÂN TÂM UY TÍNH NHẤT</strong></span></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#008000;font-size:12pt;&#34;><strong>CHUYÊN ĐÀO TẠO PHA CHẾ MỞ QUÁN KINH DOANH TRÀ SỮA, CAFE CHUYÊN NGHIỆP NHẤT, </strong></span></p>\n<p style=&#34;text-align:center;&#34;><span style=&#34;color:#008000;font-size:12pt;&#34;><strong>YÊN TÂM MỞ QUÁN KINH DOANH HIỆU QUẢ</strong></span></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><a title=&#34;khoa hoc pha che tra sua ngon&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-tra-sua-tran-chau-tra-thai-34.html&#34;><img src=&#34;http://phache.com.vn/upload/image/link-day-pha-che-tra-sua_4.png&#34; alt=&#34;lam tra sua&#34; width=&#34;1000&#34; height=&#34;50&#34; /></a></p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;> </p>\n<p style=&#34;text-align:center;&#34;><a title=&#34;lop pha che cafe chuyen nghiep&#34; href=&#34;http://phache.com.vn/cac-khoa-hoc-day-pha-che/day-pha-che-cafe-take-away-smoothies-bartender-37.html&#34;><img src=&#34;http://phache.com.vn/upload/image/lop-hoc-cafe.png&#34; alt=&#34;lop pha